import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  const [seconds, setSeconds] = useState(0);
  const [clicks, setClicks] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      setSeconds(s => s + 1);
    }, 1000);
  }, [clicks]);

  return (
    <div>
      <h2 id="seconds">Seconds: {seconds}</h2>
      <h2 id="clicks">Clicks: {clicks}</h2>
      <button id="increment" onClick={() => setClicks(clicks + 1)}>
        Increment
      </button>
    </div>
  );
}

export default App;

