import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Missing Cleanup', () => {
  test('Component renders correctly', async () => {
    const { container: root } = render(<App />);
    const s = root.querySelector('#seconds');
const c = root.querySelector('#clicks');
if (!s) throw new Error('No #seconds element');
if (!c) throw new Error('No #clicks element');
  });

  test('Increment button updates clicks', async () => {
    const { container: root } = render(<App />);
    root.querySelector('#increment').click();
await tick();
const el = root.querySelector('#clicks');
if (!el.textContent.includes('1')) throw new Error('Clicks should be 1');
  });

  test('useEffect returns a cleanup function', async () => {
    const { container: root } = render(<App />);
    // Click multiple times rapidly and check timer doesn't accelerate
root.querySelector('#increment').click();
root.querySelector('#increment').click();
root.querySelector('#increment').click();
const before = parseInt(root.querySelector('#seconds').textContent.match(/\d+/)[0]);
// If cleanup is missing, multiple intervals are stacking up
// We can't easily test timing, but we check the code structure via render stability
const el = root.querySelector('#seconds');
if (!el) throw new Error('Timer should still be rendering');
  });
});
